$_MODULE['<{priceandorder}prestashop>_settings_ae3ed16ac04bd25713c4946a81f762ac'] = 'Localidad / Ciudad';
$_MODULE['<{priceandorder}prestashop>_settings_b5ae6ed75e19e88327db2f506b9b3b25'] = 'Campos del formulario a solicitar';
$_MODULE['<{priceandorder}prestashop>_settings_bae7bc790af355d1f70ba3ba80466288'] = 'Enlace opcional mostrado bajo el formulario, p. ej. una página que explique cómo funcionan los presupuestos.';
$_MODULE['<{priceandorder}prestashop>_settings_bc30fcd520aef7d39eea1848ad6d75b3'] = 'Preguntar si este sería su primer pedido';
