$_MODULE['<{priceandorder}prestashop>_settings_dd7bf230fde8d4836917806aff6a6b27'] = 'Dirección';
$_MODULE['<{priceandorder}prestashop>_settings_e6c2a67a11a1dfa4514cda4115f31fec'] = 'Notificaciones y enlaces';
$_MODULE['<{priceandorder}prestashop>_settings_f3533a2e4c824994e48a0ef4414d8e90'] = 'Cantidad necesaria';
$_MODULE['<{priceandorder}prestashop>_settings_fdbf7ea71413939836ccc4d8f21240e9'] = 'Destino de envío';
$_MODULE['<{priceandorder}prestashop>_tutorial_0335b6ca536d6d636bdf088442b44790'] = 'Compruebe la dirección destinataria en Configuración por errores tipográficos, revise su carpeta de spam y confirme que el correo saliente funciona probando otro módulo o Parámetros avanzados > Correo electrónico. Cada solicitud se guarda en la pestaña Solicitudes de presupuesto de todos modos, así que siempre puede encontrarla allí.';
$_MODULE['<{priceandorder}prestashop>_tutorial_0431a668e8d90860362093b461947781'] = 'Envíe una solicitud de prueba desde su tienda y compruebe que llega a la pestaña Solicitudes de presupuesto y a su buzón.';
$_MODULE['<{priceandorder}prestashop>_tutorial_106e29c08b607e3b79c61dc35b0289a7'] = 'No recibo correos de solicitudes de presupuesto.';
$_MODULE['<{priceandorder}prestashop>_tutorial_231cf4c70d866b616c21baddaeed0696'] = 'Solución de problemas';
$_MODULE['<{priceandorder}prestashop>_tutorial_46ec8e9cec078e1824c2285289a9845a'] = 'Casi siempre se debe a la protección antispam automática: enviar el formulario en menos de 3 segundos tras cargar la página, enviarlo más de una hora después de cargar la página, o más de 5 solicitudes en una hora desde la misma conexión. Pídales que recarguen la página e inténtenlo de nuevo.';
$_MODULE['<{priceandorder}prestashop>_tutorial_487e540af0ce1574b40b98daaf9a704e'] = 'Un visitante dice que el formulario rechazó su envío.';
$_MODULE['<{priceandorder}prestashop>_tutorial_6d08bb064fa0dc50df631711d8f9a10a'] = 'La tarjeta de notificación del Panel de control no aparece.';
$_MODULE['<{priceandorder}prestashop>_tutorial_738cfeba525f1715b35cdbae92e826d9'] = 'Mi imagen promocional se ve estirada o se rechaza.';
$_MODULE['<{priceandorder}prestashop>_tutorial_775956a2316b82459c84f10d788864d5'] = '¿Necesita más ayuda? Contacto';
$_MODULE['<{priceandorder}prestashop>_tutorial_7f1b3b7557f81bb527614a601f1df990'] = 'Elija qué campos opcionales solicitar a los visitantes (dirección, teléfono, cantidad...).';
$_MODULE['<{priceandorder}prestashop>_tutorial_813ce2687d65c0253de66d80cddab8f3'] = 'El bloque lateral y el botón flotante comparten el mismo formulario; un visitante puede usar cualquiera de los dos.';
$_MODULE['<{priceandorder}prestashop>_tutorial_958aae0a194da728c36d3e7221675a84'] = 'El formulario no aparece en la tienda.';
$_MODULE['<{priceandorder}prestashop>_tutorial_9ffdb95250e26c7a6b468126ac7c75b0'] = 'Cómo funciona';
$_MODULE['<{priceandorder}prestashop>_tutorial_a7821d5fcb146c5ad0b90884e504d314'] = 'Las subidas se limitan a archivos JPG, PNG, GIF o WEBP de hasta 4 MB y se redimensionan automáticamente para ajustarse a 400x280 px manteniendo sus proporciones, por lo que el archivo en sí nunca se distorsiona.';
$_MODULE['<{priceandorder}prestashop>_tutorial_bc9e9fef06497c843ddb85f457c24635'] = 'A los clientes registrados nunca se les pide su nombre ni su correo electrónico &mdash; se usan automáticamente los datos de su cuenta.';
$_MODULE['<{priceandorder}prestashop>_tutorial_bd4b0999a932632905b77cd2fbc0a97c'] = 'La protección antispam es automática: un campo trampa oculto y una comprobación de retraso breve bloquean silenciosamente los envíos automatizados, y no se aceptan más de 5 solicitudes por hora del mismo visitante. Un visitante real no tiene que resolver nada.';
$_MODULE['<{priceandorder}prestashop>_tutorial_cb59b87e00d11222bfd9159d0d23836f'] = 'Primeros pasos';
$_MODULE['<{priceandorder}prestashop>_tutorial_e41d93a6e7c1aa5aab80cb4cab9dc886'] = 'Aparece una tarjeta de notificación en su Panel de control cuando hay nuevas solicitudes, con un enlace directo a esta pestaña Solicitudes de presupuesto. Desaparece cuando cada nueva solicitud se marca como gestionada o se elimina.';
$_MODULE['<{priceandorder}prestashop>_tutorial_ea67abf8988cbc6b378a032f822801f8'] = 'Abra la pestaña Configuración e introduzca la(s) dirección(es) de correo electrónico que deben recibir las solicitudes de presupuesto.';
$_MODULE['<{priceandorder}prestashop>_tutorial_f9459c8296e5294ec5990a767724198b'] = 'Faltan los enlaces de Términos y condiciones / Política de privacidad o son incorrectos.';
$_MODULE['<{priceandorder}prestashop>_tutorial_fe920a7d738e80a23e8675183ec4450d'] = 'Cada envío se guarda en la pestaña Solicitudes de presupuesto aunque falle la entrega del correo de notificación, para que no se pierda nada.';
